	v := r.Field.Type.Value
	// Value examples: "T", "MyInt", "Set[T]", "Pair[A, B]", "*T"? No, star stripped, so "T" for *T? For **? Value "*int"? Need to handle.
	// For generic: "Set[T]" -> want "Set"
