		s = s[idx+1:]
	}
	// For generic like "Set[T]", take before "["? e.g., "Set[T]" => "Set"? Embedded generic? Unlikely, but handle.
	if idx := strings.Index(s, "["); idx >= 0 {
		s = s[:idx]
	}
	return s
