func containsIdent(s, ident string) bool {
	n := len(s)
	m := len(ident)
	for i := 0; i+ m <= n; i++ {
		if s[i:i+m] == ident {
			// Check boundaries
			beforeOk := i == 0 || !(isLetter(s[i-1]) || isDigit(s[i-1]) || s[i-1] == '_')
			afterOk := i+m == n || !(isLetter(s[i+m]) || isDigit(s[i+m]) || s[i+m] == '_')
			if beforeOk && afterOk {
				return true
			}
		}
	}
	return false
}
