func buildNosubErrArgs(nosubNameArg, inputExtra, last string) string {
	// nosubNameArg like "tt.name, " or "name, ", inputExtra like ", tt.args.a, tt.args.b" or "", last like "err, tt.wantErr"
	var parts []string
	parts = append(parts, strings.TrimSuffix(nosubNameArg, ", "))
	if inputExtra != "" {
		parts = append(parts, strings.TrimPrefix(inputExtra, ", "))
	}
	parts = append(parts, last)
	return strings.Join(parts, ", ")
}

func buildNosubWantArgs(nosubNameArg, inputExtra, got, want string) string {
	var parts []string
	parts = append(parts, strings.TrimSuffix(nosubNameArg, ", "))
	if inputExtra != "" {
		parts = append(parts, strings.TrimPrefix(inputExtra, ", "))
	}
	parts = append(parts, got, "tt."+want)
	return strings.Join(parts, ", ")
}

func buildNosubWantArgsWithGot(nosubNameArg, inputExtra, got, want, msgPart string) string {
	return buildNosubWantArgs(nosubNameArg, inputExtra, got, want)
}
