	wants, wantsTypesRaw, _ := wantGotNames(fn.Results, fn.ReturnsError)
	var wantsTypes []string
	for _, wt := range wantsTypesRaw {
		wantsTypes = append(wantsTypes, instantiateType(wt, fn.TypeParams))
	}
