	} else {
		b.WriteString("tests := []struct {\n")
	}
	if !opts.Named {
		b.WriteString("\tname string\n")
	}
	if useFields {
		b.WriteString("\tfields fields\n")
	} else if fn.Receiver != nil {
		recvName := fn.Receiver.Field.Name
		recvType := instantiateType(fn.Receiver.Field.Type.String(), fn.TypeParams)
		b.WriteString(fmt.Sprintf("\t%s %s\n", recvName, recvType))
	}
