		if opts.Template == "testify" && opts.TemplateDir == "" {
			b.WriteString("\tassertion assert.ErrorAssertionFunc\n")
		} else {
			b.WriteString("\twantErr bool\n")
		}
	}
	b.WriteString("} {\n")
	b.WriteString("\t// TODO: Add test cases.\n")
	b.WriteString("}")
	return b.String()
}

func buildExampleFormat(fn *Function, opts *Options, fileStyle bool) string {
	var b strings.Builder
	b.WriteString("{\n")
	b.WriteString("    name: \"descriptive test name\",\n")
