		for _, f := range fn.Receiver.Fields {
			fparts = append(fparts, fmt.Sprintf("%s: <value>", f.Name))
		}
		b.WriteString(fmt.Sprintf("    fields: fields{%s},\n", strings.Join(fparts, ", ")))
	} else if fn.Receiver != nil {
