		// Actually for dir-style, AI would need to generate receiver values. Example format likely includes receiver? Let's include: "    <recv>: <value>,\n"
		recvName := fn.Receiver.Field.Name
		b.WriteString(fmt.Sprintf("    %s: <value>,\n", recvName))
	}
	var argParams []*Field
	for _, p := range fn.Parameters {
		if p.Type.IsWriter && !p.Type.IsVariadic {
			continue
		}
		argParams = append(argParams, p)
	}
	if len(argParams) > 0 {
		var aparts []string
		for _, p := range argParams {
			aparts = append(aparts, fmt.Sprintf("%s: <value>", p.Name))
		}
		b.WriteString(fmt.Sprintf("    args: args{%s},\n", strings.Join(aparts, ", ")))
	}
	wants, _, _ := wantGotNames(fn.Results, fn.ReturnsError)
	for _, w := range wants {
		b.WriteString(fmt.Sprintf("    %s: <expected_value>,\n", w))
	}
	_, _, writerWants, _ := callArgsAndWriters(fn.Parameters, fn.TypeParams)
	for _, ww := range writerWants {
		b.WriteString(fmt.Sprintf("    %s: <expected_value>,\n", ww))
